  const ticks = computeNiceTicks(minVal, maxVal);
  const scaleMin = ticks[0];
  const scaleMax = ticks[ticks.length - 1];
  parts.push(
    `<line x1="${round2(x)}" y1="${round2(y + h)}" x2="${round2(x + w)}" y2="${round2(y + h)}" stroke="#D9D9D9" stroke-width="1"/>`
  );
  parts.push(
    `<line x1="${round2(x)}" y1="${round2(y)}" x2="${round2(x)}" y2="${round2(y + h)}" stroke="#D9D9D9" stroke-width="1"/>`
  );
  parts.push(renderValueAxisLabels(ticks, scaleMin, scaleMax, x, y, h));
  for (let c = 0; c < catCount; c++) {
    const label = categories[c] ?? "";
    const labelX = x + (c + 0.5) * (w / catCount);
    parts.push(
      `<text x="${round2(labelX)}" y="${round2(y + h + 15)}" text-anchor="middle" font-size="10" fill="#595959">${escapeXml(label)}</text>`
    );
  }
  const range = scaleMax - scaleMin;
  for (let c = 0; c < catCount; c++) {
    const cx = x + (c + 0.5) * (w / catCount);
    const highVal = highSeries.values[c] ?? 0;
    const lowVal = lowSeries.values[c] ?? 0;
    const closeVal = closeSeries.values[c] ?? 0;
    const highY = y + h - (highVal - scaleMin) / range * h;
    const lowY = y + h - (lowVal - scaleMin) / range * h;
    const closeY = y + h - (closeVal - scaleMin) / range * h;
    parts.push(
      `<line x1="${round2(cx)}" y1="${round2(highY)}" x2="${round2(cx)}" y2="${round2(lowY)}" stroke="#404040" stroke-width="2"/>`
    );
    const tickW = w / catCount * 0.2;
    parts.push(
      `<line x1="${round2(cx)}" y1="${round2(closeY)}" x2="${round2(cx + tickW)}" y2="${round2(closeY)}" stroke="#404040" stroke-width="2"/>`
    );
  }
